#!/usr/bin/perl
# ARC-0007: puts the countdown into ARCANA_Aspect_Common.txt.
#   - the Display / ShowNumber block (from the first PROC_ARCANA_Aspect_Display to the end of the last ShowNumber) is
#     replaced by 20_common_display.txt (generated by gen_awakening_progress.pl);
#   - the Star and Death show modes PERCENT -> HEAL / LOSS.
# Exact anchors, CRLF kept; changes nothing if an anchor is missing; idempotent.
#   perl apply_common.pl            # shows what it would do
#   perl apply_common.pl --apply    # writes (game and Toolkit closed, [fechado] ARC-0007)
use strict; use warnings;
use File::Basename qw(dirname);
use Cwd qw(abs_path);
my $G = $ENV{BG3_DATA} // 'C:/Program Files (x86)/Steam/steamapps/common/Baldurs Gate 3/Data';
my $M = 'AspectClass_9d734fbd-cb67-95c0-e2c9-46f05fe2f8a7';
my $F = "$G/Mods/$M/Story/RawFiles/Goals/ARCANA_Aspect_Common.txt";
my $apply = grep { $_ eq '--apply' } @ARGV;
my $new = do { open my $h, '<:raw', abs_path(dirname(__FILE__)) . '/20_common_display.txt' or die "20_common_display.txt: $!"; local $/; <$h> };
open my $h, '<:raw', $F or die "$F: $!"; local $/; my $s = <$h>; close $h;
my $bad = 0;
if ($s =~ /ARC-0007 \(GENERATED/) { print "already  countdown block\n" }
else {
    my $start = "PROC\r\nPROC_ARCANA_Aspect_Display((CHARACTER)_Char, (STRING)_Aspect, (INTEGER)_Value)\r\nAND\r\nNOT DB_ARCANA_AspectNext(_Char, _)\r\n";
    my $end = "PROC_ARCANA_Aspect_ShowNumber((CHARACTER)_Char, (STRING)_Progress, (INTEGER)_N)\r\nAND\r\n_N < 1\r\nTHEN\r\nRemoveStatus(_Char, _Progress, _Char);\r\n";
    my ($i, $j) = (index($s, $start), index($s, $end));
    if ($i < 0 || $j < $i || index($s, $start, $i + 1) >= 0) { print "ANCHOR   the Display block\n"; $bad++ }
    else { substr($s, $i, $j + length($end) - $i) = $new; print(($apply ? 'write    ' : 'would    ') . "the countdown block\n") }
}
for my $m (['STAR', 'HEAL'], ['DEATH', 'LOSS']) {
    my ($a, $mode) = @$m;
    if ($s =~ s/DB_ARCANA_AspectShow\("$a", "PERCENT"\);/DB_ARCANA_AspectShow("$a", "$mode");/) { print(($apply ? 'write    ' : 'would    ') . "$a -> $mode\n") }
    elsif ($s =~ /DB_ARCANA_AspectShow\("$a", "$mode"\);/) { print "already  $a $mode\n" }
    else { print "ANCHOR   $a show row\n"; $bad++ }
}
if ($apply && !$bad) { open $h, '>:raw', $F or die "$F: $!"; print $h $s; close $h }
exit($bad ? 1 : 0);
